// META_ANALYSIS_v1 (v0.4) - extraction des effets (LLM) + pooling inverse-variance
// fixe + aleatoire (DerSimonian-Laird), heterogeneite Q/I2/tau2, intervalle de prediction,
// test d'Egger, forest plot + funnel plot (SVG). Mesures: OR/RR/HR (log) et MD/SMD (lineaire).
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const articles = items.map(i => i.json);
const a0 = articles[0] || {};
const OUTCOME = (a0._meta_outcome || a0.question || '').toString();
let MEASURE = (a0._meta_measure || 'auto').toString().toUpperCase();
// J2 : ajustement de Hartung-Knapp-Sidik-Jonkman - OPTION, DESACTIVEE PAR DEFAUT.
// L IC du modele aleatoire (DerSimonian-Laird) est calcule avec le quantile normal 1,96 :
// a petit nombre d etudes ou en presence de forte heterogeneite il est trop etroit (le taux
// d erreur reel depasse largement les 5% annonces). L option remplace ce quantile par un t
// a k-1 ddl et repondere l erreur type. Elle CHANGE des chiffres publiables : elle doit donc
// etre demandee explicitement (_meta_hksj sur articles[0]), et la methode retenue est nommee
// dans le resume (summary.random_ci_method) pour qu un ecart entre deux versions reste
// explicable. Sans l option, les chiffres sont strictement ceux des versions precedentes.
function _truthyUL(v){ return /^(1|true|on|oui|yes)$/i.test(String(v==null?'':v).trim()); }
const HKSJ = _truthyUL(a0._meta_hksj);
const LOGM = { OR:1, RR:1, HR:1 };
console.log('[Meta] ' + articles.length + ' articles, mesure=' + MEASURE);

function extractJson(raw){ if(!raw) return null; let s=String(raw).replace(/```json/gi,'').replace(/```/g,''); const i=s.indexOf('{'),j=s.lastIndexOf('}'); if(i<0||j<=i) return null; const f=s.substring(i,j+1); try{return JSON.parse(f);}catch(e){} try{return JSON.parse(f.replace(/,\s*([}\]])/g,'$1'));}catch(e){} return null; }
// === E9 : DES NOMBRES SURS VERS LA META-ANALYSE (2026-10-16) ===
// LA LECTURE PRENAIT LE DEBUT DE LA CHAINE, SANS RIEN DIRE. `num` valait `parseFloat`, qui
// s'arrete au premier caractere inconnu. Or la relecture humaine enregistre des CHAINES
// (/api/run/set-extracted, champ de texte libre) et les PDF rendent le signe moins typographique.
// MESURE sur le noeud livre (base 2c1df8c) : « 0,62 » -> 0 ; « 12,5 » -> 12 ; « 1 204 » avec
// espace fine -> 1 ; « 1,234.5 » -> 1 ; signe moins U+2212 -> rien ; point median U+00B7 -> 0.
// Deux etudes continues validees en ecriture francaise donnaient une DMS de -0,713
// [-1,041 ; -0,385] ; les memes chiffres ecrits a l'anglaise donnent -0,577 [-0,902 ; -0,252].
// La lecture suit la table de normalisation de la conception (brique 5) : espaces fines U+2009,
// U+202F et insecable U+00A0 ; signe moins U+2212 et tirets U+2010 a U+2015 ; point median entre
// deux chiffres ; virgule decimale ; separateur des milliers (espace, ou virgule et point quand
// les deux figurent). UNE ECRITURE AMBIGUE N'EST PAS DEVINEE : « 1,204 » vaut 1 204 a l'anglaise
// et 1,204 a la francaise ; elle rend null et le resume la compte (summary.validation). La
// tolerance de `parseFloat` pour la fin de chaine est gardee (« 12 (8.4%) » -> 12).
// TOUR 2 (2026-10-16) : LA LECTURE DE REFERENCE, ET RIEN D'AUTRE. Sa version Python est
// `provenance.nombre_depuis_texte` (etape E5), dont les cas partages (`CAS_NOMBRES`) rejouent ce
// noeud. Deux lectures fausses sans un mot, mesurees sur le premier tour : « 1 204 » ecrit avec une
// espace de chiffre U+2007 (ou U+2008, U+200A, U+205F, U+3000) valait 1, et une liste ['12', '14']
// valait 12,14. Une espace que la table ne convertit pas, suivie d'un chiffre juste apres le nombre
// de tete, rend desormais la valeur illisible, comme ce qui n'est ni une chaine ni un nombre. NFKC
// n'est pas applique : il change un appel de note en chiffre (« 12 » suivi de U+00B9 deviendrait
// 121, « 1 » suivi de U+00BD 11).
const GROUPES_MILLIERS = { ',': /^\d{1,3}(?:,\d{3})+$/, '.': /^\d{1,3}(?:\.\d{3})+$/ };
const TETE_NOMBRE = /^([+-]?)(\d[\d.,]*|[.,]\d[\d.,]*)([eE][+-]?\d+)?/;
// La chaine telle que la lecture la voit : table de la brique 5, espaces rognees aux deux bouts,
// milliers separes par une espace recolles. Partagee par `num` et par le compte des illisibles.
function nombrePrepare(x){
  return String(x)
    .replace(/[\u00A0\u2009\u202F]/g, ' ')
    .replace(/[\u2212\u2010-\u2015]/g, '-')
    .replace(/(\d)\u00B7(?=\d)/g, '$1.')
    .trim()
    .replace(/^([+-]?\d{1,3})((?: \d{3})+)(?!\d)/, function(t, tete, groupes){ return tete + groupes.split(' ').join(''); });
}
function num(x){
  if (typeof x === 'number') return isFinite(x) ? x : null;
  if (typeof x !== 'string') return null;
  const s = nombrePrepare(x);
  const m = TETE_NOMBRE.exec(s);
  if (!m) return null;
  if (/^[\u2000-\u200A\u205F\u3000]\d/.test(s.slice(m[0].length))) return null;
  const corps = m[2].replace(/[.,]+$/, '');
  const pPoint = corps.lastIndexOf('.'), pVirg = corps.lastIndexOf(',');
  let entier = corps, frac = '';
  if (pPoint >= 0 && pVirg >= 0){
    // les deux figurent : le dernier marque la decimale, l'autre separe les milliers
    const pDec = Math.max(pPoint, pVirg), sepMil = (pDec === pPoint) ? ',' : '.';
    entier = corps.slice(0, pDec); frac = corps.slice(pDec + 1);
    if (!GROUPES_MILLIERS[sepMil].test(entier)) return null;
    entier = entier.split(sepMil).join('');
  } else if (pPoint >= 0 || pVirg >= 0){
    const sep = (pVirg >= 0) ? ',' : '.';
    const parts = corps.split(sep);
    if (parts.length > 2){
      if (!GROUPES_MILLIERS[sep].test(corps)) return null;
      entier = parts.join('');
    } else if (sep === ',' && /^[1-9]\d{0,2}$/.test(parts[0]) && /^\d{3}$/.test(parts[1])){
      return null;
    } else { entier = parts[0]; frac = parts[1]; }
  }
  const v = Number(m[1] + entier + '.' + frac + (m[3] || ''));
  return isFinite(v) ? v : null;
}

// ===== J1 : quantile de Student bilateral 95% (pur JS, AUCUNE dependance) =====
// L intervalle de PREDICTION (Higgins, Thompson & Spiegelhalter 2009) est
//   mu_hat +/- t(k-2 ; 0,975) * sqrt(tau2 + var(mu_hat))
// et NON +/- 1,96 : avec 3 a 5 etudes t vaut 3,18 a 12,71 et l intervalle en 1,96 est
// faussement etroit (precision mensongere). CDF de Student via la beta incomplete reguliere
// (fraction continue de Lentz) puis inversion par dichotomie.
// MIROIR EXACT de app/src/lib/metaCalc.ts (memes constantes, memes iterations, memes arrondis).
function _lgammaUL(x){
  var g=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
  if (x<0.5) return Math.log(Math.PI/Math.sin(Math.PI*x))-_lgammaUL(1-x);
  var y=x-1, a=0.99999999999980993, t=y+7.5;
  for (var i=0;i<8;i++) a+=g[i]/(y+i+1);
  return 0.5*Math.log(2*Math.PI)+(y+0.5)*Math.log(t)-t+Math.log(a);
}
function _betacfUL(a,b,x){
  var MAXIT=300, EPS=3e-14, FPMIN=1e-300;
  var qab=a+b, qap=a+1, qam=a-1;
  var c=1, d=1-qab*x/qap;
  if (Math.abs(d)<FPMIN) d=FPMIN;
  d=1/d; var h=d;
  for (var m=1;m<=MAXIT;m++){
    var m2=2*m;
    var aa=m*(b-m)*x/((qam+m2)*(a+m2));
    d=1+aa*d; if (Math.abs(d)<FPMIN) d=FPMIN;
    c=1+aa/c; if (Math.abs(c)<FPMIN) c=FPMIN;
    d=1/d; h*=d*c;
    aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));
    d=1+aa*d; if (Math.abs(d)<FPMIN) d=FPMIN;
    c=1+aa/c; if (Math.abs(c)<FPMIN) c=FPMIN;
    d=1/d; var del=d*c; h*=del;
    if (Math.abs(del-1)<EPS) break;
  }
  return h;
}
function _ibetaUL(a,b,x){
  if (x<=0) return 0;
  if (x>=1) return 1;
  var bt=Math.exp(_lgammaUL(a+b)-_lgammaUL(a)-_lgammaUL(b)+a*Math.log(x)+b*Math.log(1-x));
  if (x < (a+1)/(a+b+2)) return bt*_betacfUL(a,b,x)/a;
  return 1-bt*_betacfUL(b,a,1-x)/b;
}
function _tcdfUL(t,df){
  var p=0.5*_ibetaUL(df/2,0.5,df/(df+t*t));
  return (t>0)?(1-p):p;
}
// t tel que P(T<=t)=0,975 pour df ddl. Renvoie null si df<1 (pas d intervalle de prediction).
function tQuantile975(df){
  if (!(df>=1)) return null;
  var lo=0, hi=1000;
  for (var i=0;i<200;i++){ var mid=0.5*(lo+hi); if (_tcdfUL(mid,df)<0.975) lo=mid; else hi=mid; }
  return 0.5*(lo+hi);
}
const PI_METHOD = 'Higgins, Thompson & Spiegelhalter : quantile de Student a k-2 ddl (bilateral 95%)';
// J2 : libelles des methodes d IC du modele aleatoire. Chaines IDENTIQUES cote interface
// (app/src/lib/metaCalc.ts) : le nom de la methode voyage avec les chiffres.
const RANDOM_CI_METHOD_DL = 'DerSimonian-Laird : intervalle de confiance par quantile normal 1,96 (methode par defaut)';
const RANDOM_CI_METHOD_HKSJ = 'DerSimonian-Laird + ajustement de Hartung-Knapp-Sidik-Jonkman : erreur type reponderee et quantile de Student a k-1 ddl (option activee)';
const HKSJ_NOTE_K = 'ajustement non applicable : il faut au moins 2 etudes (ddl = k-1 >= 1)';
const HKSJ_NOTE_Q = 'ajustement non applicable : dispersion nulle entre les etudes (q = 0), il donnerait un intervalle de largeur nulle';
const HKSJ_NOTE_NARROW = 'attention : ici l ajustement RESSERRE l intervalle (q < 1, etudes tres concordantes) au lieu de l elargir';
// q = somme(w* (yi - mu)^2) / (k-1) ; var_HK = q / somme(w*) ; IC = mu +/- t(k-1 ; 0,975) * sqrt(var_HK).
// Deux cas degeneres traites explicitement : k < 2 (ddl = k-1 = 0, division par zero) et q = 0
// (etudes strictement concordantes : l IC serait de largeur nulle, precision mensongere).
// Dans ces deux cas l ajustement N EST PAS applique et l IC reste celui de DerSimonian-Laird.
function hksjStats(yis, wstars, sumWs, mu){
  var kk=yis.length, dfHK=kk-1;
  if (!(kk>=2)) return { available:false, df:dfHK, t:null, se:null, q:null, note:HKSJ_NOTE_K };
  var sHK=0;
  for (var i=0;i<kk;i++){ sHK+=wstars[i]*Math.pow(yis[i]-mu,2); }
  var qHK=sHK/(kk-1);
  var varHK=qHK/sumWs;
  var seHK=Math.sqrt(varHK);
  var tHK=tQuantile975(dfHK);
  if (!isFinite(seHK) || !(seHK>0) || tHK==null)
    return { available:false, df:dfHK, t:null, se:null, q:isFinite(qHK)?qHK:null, note:HKSJ_NOTE_Q };
  return { available:true, df:dfHK, t:tHK, se:seHK, q:qHK };
}
const ZERO_METHOD = 'correction de continuite 0,5 sur les zeros simples ; etudes a double zero exclues du poolage des rapports (Cochrane Handbook 10.4.4.1)';

// E9 (2026-10-16) : QUI A VALIDE LES CHIFFRES D'UN ARTICLE.
// TOUR 2 (2026-10-16) : LA REGLE DE L'INDEX DES TACHES, ET ELLE SEULE. Le premier tour jetait le
// badge `_human_verified` quand l'article portait `_rob_level`, pris pour la trace de
// /api/run/set-rob, ou `_uoa_action` sur `_meta_data`, pris pour celle de /api/run/set-uoa. Or le
// MODULE de risque de biais ecrit `_rob_level` sur chaque article qu'il evalue (« unknown »
// compris, workflows/ultralab-riskofbias.json). MESURE dans l'ordre de la chaine (extraction,
// biais, meta) : deux etudes corrigees a 10/100 et 12/100 par /api/run/set-extracted, dont
// `_meta_data` gardait 30/100 et 28/100, donnaient encore l'OR des chiffres perimes, 1,00
// [0,649 ; 1,54], et « 8 valeurs sur 8 sans validation ». Le badge se lit desormais par la regle
// de `index_taches.chiffres_verifies` (src/index_taches.py), qui en separe les sens :
// /api/run/set-rob ecrit `_rob_human_verified`, /api/run/set-uoa n'ecrit plus de badge.
// Meme verite qu'en Python : vide, zero et faux ne valent rien. Le mode est celui de ce run : le
// noeud ne tourne que dans la branche « meta-analysis » du module, dont « Prepare Articles » nomme
// le dossier « ultralab-module-meta-analysis-<horodatage> », ou `mode_du_run` lit
// « meta-analysis ». La trace par champ `_extraction_valide` de la conception (brique 9) est lue
// par la regle 1 bis (2026-10-17, ci-dessous), comme en Python.
// TOUR 3 (2026-10-16) : LA REGLE DU TOUR 3 DU LOT « BADGE », EN ENTIER ET DANS SON ORDRE. Le noeud
// reprenait celle du tour 2 de ce lot, qui ne voyait que la correction du biais. MESURE de la
// verification du tour 2 (vraies routes, puis ce noeud) : un run de meta ecrit avant ce jour, ou
// l'ancienne route /api/run/set-uoa a pose `_human_verified` a cote de sa correction (trace
// `_meta_data._uoa_action`), disait « 8 valeurs, dont 0 sans validation humaine attestee » pour
// des chiffres du modele que personne n'avait relus. La regle, reprise telle quelle :
//   1. sans le badge, non ;
//   1 bis. un champ attend encore un geste humain (`unChampAttend`, 2026-10-17), non ;
//   2. article d'une fusion ecrite avant ce jour (`_merge_sources` sans `_merge_badges_lus`) : non
//      s'il a plusieurs sources, ou une seule qui est elle-meme un dossier de fusion (tour 4 du
//      lot « badge ») ; sinon le mode est celui de son unique source ;
//   3. badge AMBIGU, que la correction du biais (clef `_rob_items_original` presente et clef
//      `_rob_human_verified` ABSENTE : ecrite a faux, elle compte comme presente) ou celle de
//      l'unite d'analyse (`_meta_data._uoa_action` vrai et marque `_uoa_sans_badge` fausse) a pu
//      poser avant ce jour : oui seulement si la clef `_extracted_original` est presente et la
//      clef `_imputed` absente ;
//   4. run d'extraction : oui seulement avec `_extracted_original` ;
//   5. sinon, oui.
// Ce que /api/run-articles sert, et ce que le planificateur transmet (src/pipeline.py), est deja lu
// par cette regle (le badge servi est sa reponse, la correction d'unite porte sa marque) : sur ces
// chemins les regles 2 et 3 ne jouent pas, et elles tiennent pour un article qui arrive tel que son
// run l'enregistre. Deux cas croises executent les deux regles sur les memes articles, toutes
// formes croisees, la regle seule et le noeud entier (tests/test_meta_nombres_surs.py).
const CLE_BIAIS_VERIFIE = '_rob_human_verified';
const MARQUE_UNITE_SANS_BADGE = '_uoa_sans_badge';
const MARQUE_FUSION_LUE = '_merge_badges_lus';
const MODE_EXTRACTION = 'extraction';
const MODE_DU_RUN = 'meta-analysis';
function vraiPy(v){
  if (v != null && typeof v === 'object') return Object.keys(v).length > 0;
  return !!v;
}
function porte(a, k){ return Object.prototype.hasOwnProperty.call(a, k); }
// `index_taches.mode_du_run(nom)` sans article. Python lit `str(nom)` : seule une chaine peut
// commencer par le prefixe (une liste imbriquee, que `String()` aplatirait, n'y commence pas).
function modeDuRun(nom){
  const prefixe = 'ultralab-module-';
  if (typeof nom !== 'string' || nom.indexOf(prefixe) !== 0) return '';
  return nom.slice(prefixe.length).split('-20')[0];
}
// `_badge_ancien_du_biais` et `_badge_ancien_de_l_unite`, le badge etant deja vrai ici (regle 1).
// Hors d'un objet, `_meta_data` ne porte aucune correction d'unite : une liste, une chaine ou un
// nombre n'ont pas la propriete ; seul nul se garde.
function badgeAncienDuBiais(a){
  return !porte(a, CLE_BIAIS_VERIFIE) && porte(a, '_rob_items_original');
}
function badgeAncienDeLUnite(a){
  const md = a._meta_data;
  return md != null && vraiPy(md._uoa_action) && !vraiPy(md[MARQUE_UNITE_SANS_BADGE]);
}
// `_sources_d_une_fusion_d_avant`.
function sourcesDUneFusionDAvant(a){
  if (!porte(a, '_merge_sources') || vraiPy(a[MARQUE_FUSION_LUE])) return null;
  return Array.isArray(a._merge_sources) ? a._merge_sources : [];
}
// `index_taches._fusion_d_avant_sans_preuve` (2026-10-17, tour 4 du lot « badge »). La fusion
// d'avant ce jour remplacait les sources de la copie recopiee par le seul nom du dossier lu :
// l'article d'une fusion de fusion n'a qu'une source, le dossier de la fusion interne, quel que
// soit le nombre de copies qu'elle reunissait. Il ne prouve donc rien. Python lit `str()` de la
// source : seule une chaine peut commencer par le prefixe.
const PREFIXE_FUSION = 'ultralab-merge-';
function estUnDossierDeFusion(nom){
  return typeof nom === 'string' && nom.indexOf(PREFIXE_FUSION) === 0;
}
// REGLE 1 BIS (2026-10-17, etape E7 de l'extraction) : `index_taches.champs_en_attente` n'est
// pas vide. CE QUI ETAIT FAUX : la regle Python ne vaut le badge que si aucun champ n'attend
// encore un geste humain, et ce noeud l'ignorait. MESURE (tests/test_meta_nombres_surs.py,
// harnais du noeud) : un article au badge pose, avec `_extracted_original` et
// `_extraction_a_relire` ["effect"], etait juge valide ici et non valide en Python ; le noeud
// entier prenait ses chiffres dans `_extracted` et les comptait valides. Un champ attend : une
// chaine de `_extraction_a_relire` (une liste), ou une valeur « proposee » de
// `_extraction_arbitrage` que `_extraction_valide` ne valide pas par une entree objet a elle.
// Seul le fait qu'un champ attende compte ici : la liste n'est pas formee. Un objet au sens de
// Python : ni nul, ni tableau.
function objetPy(v){ return v != null && typeof v === 'object' && !Array.isArray(v); }
function unChampAttend(a){
  const relire = a._extraction_a_relire;
  if (Array.isArray(relire) && relire.some(function (c){ return typeof c === 'string'; })) return true;
  const arbitrage = a._extraction_arbitrage, valide = a._extraction_valide;
  if (!objetPy(arbitrage)) return false;
  return Object.keys(arbitrage).some(function (c){
    const d = arbitrage[c];
    const validee = objetPy(valide) && porte(valide, c) && objetPy(valide[c]);
    return objetPy(d) && d.decision === 'proposee' && !validee;
  });
}
function chiffresVerifies(a, mode){
  if (!vraiPy(a._human_verified)) return false;
  if (unChampAttend(a)) return false;
  const sources = sourcesDUneFusionDAvant(a);
  if (sources !== null){
    if (sources.length !== 1 || estUnDossierDeFusion(sources[0])) return false;
    mode = modeDuRun(sources[0]);
  }
  if (badgeAncienDuBiais(a) || badgeAncienDeLUnite(a)) return porte(a, '_extracted_original') && !porte(a, '_imputed');
  if (mode === MODE_EXTRACTION) return porte(a, '_extracted_original');
  return true;
}

// E9 : LES SOURCES DE CHAQUE ARTICLE, gardees HORS de l'article (elles ne servent qu'au choix du
// bloc et au compte du resume) : `ordre`, les blocs candidats dans l'ordre de preference ;
// `bruts`, les objets lus, dans le meme ordre (`_extracted`, `_meta_data`, reponse du modele) ;
// `valide`, la regle ci-dessus. Le choix (`pris`) se fait une fois la mesure connue.
const CHOIX = new Map();
const COMPTE_VALIDATION = { utilisees: 0, validees: 0, etudes_non_validees: 0, illisibles: 0 };
// Une valeur ECRITE COMME UN NOMBRE que `num` refuse (ecriture ambigue ou mal formee) est comptee,
// jamais devinee. TOUR 2 : une mention d'absence qui porte un chiffre (« not reported (see
// Table 2) ») n'est pas un nombre mal ecrit ; le premier tour la comptait.
function illisible(x){
  return num(x) == null && /^[+-]?(?:\d|[.,]\d)/.test(nombrePrepare(x));
}

// PONT EXTRACTION -> META (interactivite 0.4.3) : reutilise des donnees chiffrees deja
// disponibles (module Extraction preset "meta-ready", cle=schema meta ; OU _meta_data
// d'un run precedent) plutot que de relancer un appel LLM. Rend null si rien
// d'exploitable -> extraction LLM classique (retro-compatible).
//
// E9 (2026-10-16) : LES CHIFFRES VALIDES PASSENT AVANT CEUX D'UN RUN PRECEDENT. `_meta_data`
// etait relu en premier des qu'il existait. Or il porte les chiffres du run de meta precedent
// (repris de `_extracted` a ce moment-la, ou lus par le modele de la meta), et le chainage le
// transmet avec `_extracted` (src/corpus_chainage.py). Une correction validee ensuite etait donc
// ignoree sans un mot. MESURE sur le noeud livre : deux etudes corrigees et validees a 10/100
// contre 30/100 et 12/100 contre 28/100, dont le run precedent avait garde 30/100 et 28/100 dans
// l'intervention, donnaient un OR groupe de 1,00 [0,649 ; 1,54].
// TOUR 2 (2026-10-16) : LE BLOC SE CHOISIT AVEC LA MESURE. Le premier tour prenait le premier bloc
// de `_extracted` valide (binaire avant tout) sans regarder la mesure demandee. MESURE : un
// relecteur complete a la main les effectifs de deux etudes dont le premier run n'avait lu que le
// HR, et valide ; en mesure HR, le bloc binaire passait devant le HR et les deux etudes sortaient
// du calcul (k = 0, contre k = 2 et HR 0,8 [0,646 ; 0,991] sur la base). reuseExisting ne fait
// donc plus que relever les candidats : les blocs de `_extracted` puis `_meta_data` quand les
// chiffres sont valides, l'inverse sinon. Le choix se fait une fois la mesure connue (plus bas).
// Il rend le bloc que lisait la version precedente (`_meta_data`, sinon le premier bloc de
// `_extracted`) : la mesure automatique s'en deduit comme avant, et une validation ne change pas
// en silence la mesure de tout le corpus. Les corrections d'unite d'analyse (`_uoa_*`) et le devis
// poses sur `_meta_data` suivent les blocs de `_extracted`, meme quand `_meta_data` ne porte que
// ces corrections (le premier tour les perdait alors, comme la base).
// TOUR 2 : UN INSTANTANE DE `_extracted` NE PASSE PAS DEVANT `_extracted`. Un `_meta_data` marque
// `_reused` est la copie d'un bloc de `_extracted` prise par un run precedent ; seul /api/run/set-uoa
// y ecrit ensuite, et ses corrections suivent. Le planificateur (src/pipeline.py, liste
// src/corpus_chainage.py) transmet `_extracted` et `_meta_data` mais pas les marques de relecture :
// MESURE, un run de meta corrige par /api/run/set-extracted puis recharge par le planificateur
// donnait encore l'OR des chiffres perimes, 1,00 [0,649 ; 1,54]. Les blocs de `_extracted` passent
// donc aussi devant une telle copie ; sans badge, leurs valeurs restent comptees non validees.
function reuseExisting(art){
  const md = art._meta_data;
  const mdObjet = !!(md && typeof md==='object');
  const mdOk = mdObjet && !!md.data_type && md.data_type!=='none';
  const valide = chiffresVerifies(art, MODE_DU_RUN);
  const exDabord = valide || (mdObjet && md._reused === true);
  // Les blocs que `_extracted` permet de former, dans l'ordre historique : binaire, continu, effet
  // precalcule, proportion declaree. Chacun ne porte que ses champs, comme avant.
  const ex = (art._extracted && typeof art._extracted==='object') ? art._extracted : null;
  const blocs = [];
  if (ex){
    var ei=num(ex.events_intervention), ni=num(ex.n_intervention), ec=num(ex.events_control), nc=num(ex.n_control);
    var mi=num(ex.mean_intervention), si=num(ex.sd_intervention), mc=num(ex.mean_control), sc=num(ex.sd_control);
    var eff=num(ex.effect), lo=num(ex.ci_lower), hi=num(ex.ci_upper);
    const base = function(){ return { outcome: ((ex.outcome!=null?ex.outcome:(art._meta_outcome||''))+''), design: ((ex.design||'')+'').toLowerCase()||undefined, _reused:true }; };
    if (ei!=null && ni!=null && ec!=null && nc!=null)
      blocs.push(Object.assign(base(), { data_type:'binary', events_intervention:ei, n_intervention:ni, events_control:ec, n_control:nc }));
    if (mi!=null && si!=null && ni!=null && mc!=null && sc!=null && nc!=null)
      blocs.push(Object.assign(base(), { data_type:'continuous', mean_intervention:mi, sd_intervention:si, n_intervention:ni, mean_control:mc, sd_control:sc, n_control:nc }));
    if (eff!=null && lo!=null && hi!=null)
      blocs.push(Object.assign(base(), { data_type:'precomputed', effect_measure:((ex.effect_measure||'')+'').toUpperCase()||undefined, effect:eff, ci_lower:lo, ci_upper:hi }));
    // E9 : proportion d'un seul bras, SEULEMENT si l'extraction la declare. Deduite de l'absence du
    // bras controle, elle ferait une prevalence d'un essai a deux bras dont le controle n'a pas
    // ete lu, et la mesure automatique passerait au double arcsinus pour tout le corpus.
    if (String(ex.data_type||'').trim().toLowerCase()==='proportion' && ei!=null && ni!=null)
      blocs.push(Object.assign(base(), { data_type:'proportion', events_intervention:ei, n_intervention:ni }));
  }
  const extraits = blocs.map(function(b){
    if (mdObjet){
      for (const k in md){ if (k.indexOf('_uoa_')===0) b[k] = md[k]; }
      // TOUR 3 (2026-10-16) : SANS VALIDATION, LE DEVIS DU RUN PRECEDENT PRIME. Seul un devis relu
      // et valide passe devant celui de `_meta_data`, qui ne comble alors qu'une absence. MESURE de
      // la verification du tour 2 : `_meta_data` disait « crossover » sans effet apparie, une
      // extraction que personne n'avait relue disait « RCT » ; le bloc de l'extraction levait
      // l'exclusion de l'essai croise (k = 3 contre 2 sur la base) et le devis devenait « rct ».
      if (!b.design) b.design = md.design;
      else if (!valide && md.design) b.design = md.design;
    }
    return { bloc:b, brut:ex, source:'extraction' };
  });
  const precedent = mdOk ? [{ bloc:md, brut:md, source:'precedent' }] : [];
  CHOIX.set(art, {
    ordre: exDabord ? extraits.concat(precedent) : precedent.concat(extraits),
    bruts: (exDabord ? [ex, mdOk ? md : null] : [mdOk ? md : null, ex]).filter(Boolean),
    valide: valide
  });
  if (mdOk) return md;
  return extraits.length ? extraits[0].bloc : null;
}

// === A11 : ENVOYER LES SECTIONS QUI PORTENT LES CHIFFRES ===
// Le nœud conservait 22 000 caracteres du plein texte, enregistrait « base sur le plein texte »
// et demandait une fenetre de 32 768 jetons... pour n'envoyer au modele que les 8 000 PREMIERS
// caracteres. Or les effectifs, les intervalles et les evenements vivent dans la section des
// resultats, pas dans l'introduction.
// MESURE sur 10 pleins textes reels (33 000 a 64 000 caracteres, tronques aux 22 000 conserves),
// part des reperes chiffres (n=, 12/345, 95% CI, OR=, p<) effectivement transmis :
//     debut 8 000 caracteres (avant)          21 %
//     debut 16 000 caracteres                 52 %
//     debut 3 000 + zone la plus chiffree     84 %
// Deux articles sur dix n'envoyaient AUCUN repere chiffre. On garde donc une tete de texte, qui
// porte le devis et souvent le resultat principal du resume, et on y ajoute la fenetre la plus
// dense en chiffres du reste. Le budget double, il ne triple pas.
const BUDGET_TEXTE = 16000;
const TETE_TEXTE = 3000;
const REPERES_CHIFFRES = /\b\d+\s*\/\s*\d+\b|\bn\s*=\s*\d+|95\s*%?\s*(?:CI|IC)|\b(?:OR|RR|HR|aOR|aHR|SMD|MD)\s*[=:]?\s*-?\d|\bp\s*[<=>]\s*0?\.\d+/gi;

function choisirExtrait(t){
  t = String(t||'');
  if (t.length <= BUDGET_TEXTE) return { texte: t, mode: 'entier', envoye: t.length, total: t.length };
  var pos = [], m;
  REPERES_CHIFFRES.lastIndex = 0;
  while ((m = REPERES_CHIFFRES.exec(t)) !== null){ pos.push(m.index); if (pos.length > 5000) break; }
  var reste = BUDGET_TEXTE - TETE_TEXTE;
  var apres = pos.filter(function(x){ return x >= TETE_TEXTE; });
  if (!apres.length){
    return { texte: t.substring(0, BUDGET_TEXTE), mode: 'debut_faute_de_chiffres',
             envoye: BUDGET_TEXTE, total: t.length };
  }
  var meilleur = TETE_TEXTE, score = -1;
  for (var deb = TETE_TEXTE; deb <= Math.max(TETE_TEXTE, t.length - reste); deb += 1000){
    var n = 0;
    for (var i = 0; i < apres.length; i++){ if (apres[i] >= deb && apres[i] < deb + reste) n++; }
    if (n > score){ score = n; meilleur = deb; }
  }
  // Le saut est ECRIT dans le texte transmis : sans lui le modele lirait deux passages eloignes
  // comme une suite continue, et pourrait rapprocher des chiffres qui n'ont aucun rapport.
  var extrait = t.substring(0, TETE_TEXTE)
    + String.fromCharCode(10) + '[... passage intermediaire omis ...]' + String.fromCharCode(10)
    + t.substring(meilleur, meilleur + reste);
  return { texte: extrait, mode: 'tete_plus_zone_chiffree', envoye: extrait.length, total: t.length };
}

function buildPrompt(a, text){
  return [
    'Extract the quantitative result for the MAIN outcome of this study, for a meta-analysis.',
    OUTCOME ? ('TARGET OUTCOME (focus on this if present): ' + OUTCOME.substring(0,200)) : '',
    '',
    'TITLE: ' + ((a.title||'').substring(0,200)),
    // Le texte arrive DEJA choisi (voir choisirExtrait). Recouper ici annulerait le
    // travail de selection sans que rien ne le signale.
    'TEXT: ' + (text||'').toString(),
    '',
    'Return STRICT JSON ONLY:',
    '{',
    '  "outcome": "<short outcome name>",',
    '  "design": "rct" | "nonrandomized",',
    '  "data_type": "binary" | "continuous" | "precomputed" | "proportion" | "none",',
    // Le gabarit definissait « proportion » et RIEN D'AUTRE. Un modele de 3 milliards de
    // parametres devait deviner ce que « binary », « continuous » et « precomputed »
    // attendaient de lui, alors que ce sont les trois formes les plus employees.
    '  ("binary" = events and totals in EACH group: fill events_intervention, n_intervention, events_control, n_control),',
    '  ("continuous" = mean and SD in EACH group: fill mean_intervention, sd_intervention, n_intervention, mean_control, sd_control, n_control),',
    '  ("precomputed" = an effect ALREADY reported with its 95% confidence interval: fill effect_measure, effect, ci_lower, ci_upper),',
    '  ("proportion" = single-arm prevalence/incidence: fill events_intervention + n_intervention only),',
    '  "events_intervention": <int|null>, "n_intervention": <int|null>,',
    '  "events_control": <int|null>, "n_control": <int|null>,',
    '  "mean_intervention": <num|null>, "sd_intervention": <num|null>,',
    '  "mean_control": <num|null>, "sd_control": <num|null>,',
    '  "effect_measure": "OR"|"RR"|"HR"|"MD"|"SMD"|null, "effect": <num|null>, "ci_lower": <num|null>, "ci_upper": <num|null>',
    '}',
    'Use "none" if no usable quantitative result is reported. Numbers only (no text, no %).'
  ].filter(Boolean).join('\n');
}

// E9 (2026-10-16) : les champs que chaque branche du calcul LIT, pour compter les valeurs qui
// entrent reellement dans le calcul. Un champ present mais non lu ne compte pas.
const CH_PROPORTION = ['events_intervention','n_intervention'];
const CH_BINAIRE = ['events_intervention','n_intervention','events_control','n_control'];
const CH_CONTINU = ['mean_intervention','sd_intervention','n_intervention','mean_control','sd_control','n_control'];
const CH_PRECALCULE = ['effect','ci_lower','ci_upper'];
// TOUR 2 (2026-10-16) : les branches que le calcul essaie pour chaque mesure, dans l'ordre de
// deriveEffect ; toute autre mesure (HR...) ne lit que l'effet precalcule. `champsLus` : les
// champs que le calcul a cherches, branche par branche jusqu'a celle qui a abouti (`succes`, les
// champs que rend deriveEffect), toutes quand aucune n'a abouti.
const BRANCHES = { OR:[CH_BINAIRE,CH_PRECALCULE], RR:[CH_BINAIRE,CH_PRECALCULE],
  MD:[CH_CONTINU,CH_PRECALCULE], SMD:[CH_CONTINU,CH_PRECALCULE], PFT:[CH_PROPORTION] };
function champsLus(mesure, succes){
  const out = [];
  for (const br of (BRANCHES[mesure] || [CH_PRECALCULE])){
    for (const c of br) out.push(c);
    if (br === succes) break;
  }
  return out;
}

// TOUR 3 (2026-10-16) : LE DOUBLE ARCSINUS DE FREEMAN-TUKEY ET SON INVERSE, POUR L'AFFICHAGE. La
// branche « proportion » (PFT) met en commun yi = (asin(sqrt(x/(n+1))) + asin(sqrt((x+1)/(n+1))))/2
// et publiait le resultat SUR CETTE ECHELLE comme l'effet global. MESURE de la verification du
// tour 2 : trois etudes a 12/80, 20/90 et 9/70 (proportions 0,15, 0,22 et 0,13) donnaient
// « 0,428 [0,356 ; 0,5] », 0,404 pour l'etude a 12/80, et le forest plot tracait une ligne nulle a
// 0. Le calcul reste sur l'echelle du double arcsinus (yi, vi, poolage, heterogeneite, Egger,
// funnel plot) ; l'affichage est retrotransforme par l'inversion exacte du double arcsinus pour un
// effectif donne (forme publiee en 1978, celle qu'emploie le module R, src/r_templates.py, cas
// « meta_proportion ») : l'effectif de l'etude pour ses chiffres, la moyenne harmonique des
// effectifs des etudes groupees pour le resultat groupe. Sous l'echelle minimale, ou au-dessus de
// l'echelle maximale, que cet effectif permet, la proportion vaut 0 ou 1 (entre les deux, la racine
// ne recoit jamais de nombre negatif : balayage du lot, effectifs de 1 a 100 000). Apres :
// 0,168 [0,117 ; 0,226], et 0,15 pour l'etude a 12/80, soit x/n exactement.
function pftDe(p, n){ const x = p*n; return 0.5*(Math.asin(Math.sqrt(x/(n+1))) + Math.asin(Math.sqrt((x+1)/(n+1)))); }
function ipft(t, n){
  if (t < pftDe(0, n)) return 0;
  if (t > pftDe(1, n)) return 1;
  const s = Math.sin(2*t), c = Math.cos(2*t);
  return 0.5*(1 - Math.sign(c)*Math.sqrt(1 - Math.pow(s + (s - 1/s)/n, 2)));
}

// derive yi (effect, log space si ratio) + vi pour la mesure demandee
function deriveEffect(d, measure){
  const isLog = !!LOGM[measure];
  // LOT-A F7 : proportions single-arm (PFT) - yi = double arcsinus Freeman-Tukey, vi = 1/(4n+2)
  if (measure==='PFT'){
    const x=num(d.events_intervention), nn=num(d.n_intervention);
    if (x!=null && nn!=null && nn>0 && x>=0 && x<=nn){
      const yi=0.5*(Math.asin(Math.sqrt(x/(nn+1)))+Math.asin(Math.sqrt((x+1)/(nn+1))));
      return {yi:yi, vi:1/(4*nn+2), champs:CH_PROPORTION, n:nn};
    }
    return null;
  }
  // binary -> OR / RR (donnees brutes prioritaires si presentes)
  if ((measure==='OR'||measure==='RR')){
    let a=num(d.events_intervention), n1=num(d.n_intervention), c=num(d.events_control), n2=num(d.n_control);
    if (a!=null&&n1!=null&&c!=null&&n2!=null&&n1>0&&n2>0){
      let b=n1-a, dd=n2-c;
      // J6 (Cochrane Handbook 10.4.4.1) : une etude SANS AUCUN evenement dans les deux bras
      // n apporte aucune information sur un rapport (OR/RR). Lui appliquer la correction 0,5
      // lui fabrique un OR artificiel proche de 1 qui tire le resultat groupe vers l absence
      // d effet -> elle est EXCLUE du poolage (mais comptee et signalee dans le resume).
      if (a<=0 && c<=0){ return {exclude:'double_zero'}; }
      var cc=false;
      if (a<=0||b<=0||c<=0||dd<=0){ a+=0.5;b+=0.5;c+=0.5;dd+=0.5; cc=true; }
      if (measure==='OR'){ const yi=Math.log((a*dd)/(b*c)); const vi=1/a+1/b+1/c+1/dd; return {yi:yi,vi:vi,cc:cc,champs:CH_BINAIRE}; }
      const r1=a/(a+b), r2=c/(c+dd); const yi=Math.log(r1/r2); const vi=1/a-1/(a+b)+1/c-1/(c+dd); return {yi:yi,vi:vi,cc:cc,champs:CH_BINAIRE};
    }
  }
  // continuous -> MD / SMD (donnees brutes)
  if ((measure==='MD'||measure==='SMD')){
    const m1=num(d.mean_intervention), s1=num(d.sd_intervention), n1=num(d.n_intervention);
    const m2=num(d.mean_control), s2=num(d.sd_control), n2=num(d.n_control);
    if (![m1,s1,n1,m2,s2,n2].some(function(x){return x==null;}) && n1>0 && n2>0 && s1>=0 && s2>=0){
      if (measure==='MD'){ const yi=m1-m2; const vi=(s1*s1)/n1+(s2*s2)/n2; return {yi:yi,vi:vi,champs:CH_CONTINU}; }
      const sp=Math.sqrt(((n1-1)*s1*s1+(n2-1)*s2*s2)/(n1+n2-2));
      if (sp>0){ const dd=(m1-m2)/sp; const J=1-3/(4*(n1+n2)-9); const g=J*dd; const vi=(n1+n2)/(n1*n2)+g*g/(2*(n1+n2)); return {yi:g,vi:vi,champs:CH_CONTINU}; }
    }
  }
  // effet + IC pre-calcules (fallback, quel que soit data_type)
  if (d.effect!=null && d.ci_lower!=null && d.ci_upper!=null){
    const em=(d.effect_measure||measure||'').toUpperCase();
    const pl=!!LOGM[em];
    if (em && em!==measure) return null; // mesure incompatible
    let eff=num(d.effect), lo=num(d.ci_lower), hi=num(d.ci_upper);
    if (eff==null||lo==null||hi==null||hi<=lo) return null;
    // I10 (2026-10-19, FORME MINIMALE) : L'IC RAPPORTE EST SUPPOSE A 95 %, ET C'EST DESORMAIS DIT.
    // CE QUI ETAIT FAUX : l'erreur type se deduit de la largeur de l'IC divisee par 2 x 1,96 ; un IC
    // rapporte a 90 % ou 99 % donnerait une autre erreur type, donc un autre poids, et rien ne comptait
    // les etudes concernees. MESURE sur trois HR publies avec leur IC : le resume, le rapport et les
    // statistiques du run n'en disaient rien. Le calcul ne change pas (le niveau de l'IC n'est pas lu
    // par l'extraction : c'est la forme complete, prevue avec le schema etendu) ; la marque `ic95`
    // fait compter l'etude (resume `ci_assumed_95`, rapport, statistiques du run).
    if (pl){ if(eff<=0||lo<=0||hi<=0) return null; const yi=Math.log(eff), se=(Math.log(hi)-Math.log(lo))/(2*1.96); return {yi:yi,vi:se*se,champs:CH_PRECALCULE,ic95:true}; }
    const yi=eff, se=(hi-lo)/(2*1.96); return {yi:yi,vi:se*se,champs:CH_PRECALCULE,ic95:true};
  }
  return null;
}

// ---- 1. Extraction LLM par article ----
// TOUR 3 (2026-10-16) : CE QUE CE NOEUD CALCULE NE S'HERITE PAS D'UN RUN PRECEDENT. Un run de meta
// repris comme corpus arrive avec les effets qu'il a calcules (/api/run-articles sert `_meta_yi`,
// `_meta_vi`, `_meta_effect`, les bornes, le poids et `_meta_included`). Le noeud ne les ecrivait
// que pour les etudes retenues. MESURE sur le noeud du tour 2 : une etude que ce run ecarte (unite
// d'analyse, essai croise, mesure incompatible, sans donnees, rapport secondaire) sortait avec
// l'effet, les bornes, le poids et `_meta_included` du run precedent, et les marques posees
// seulement quand elles s'appliquent (controle partage divise, correction de continuite, libelle
// hors du critere dominant) restaient aussi. Or la vue en direct (MetaLive.svelte), l'export de
// synthese (revman_export.build_grade_sof) et l'export vers le module R (routes_r) prennent tout
// article qui porte `_meta_yi` : ils comptaient une etude que le rapport ecarte. Tout ce que le
// calcul pose est donc efface a l'entree, avant tout calcul.
const CALCULE_PAR_LE_RUN = ['_meta_yi','_meta_vi','_meta_se','_meta_wstar','_meta_weight','_meta_effect',
  '_meta_ci_low','_meta_ci_high','_meta_included','_meta_zero_cc','_meta_uoa','_meta_note','_meta_raw',
  '_meta_outcome_mismatch','_meta_ci_assumed_95','_meta_ralenti','_meta_call_error'];
// I10 (2026-10-19) : la marque d'un IC suppose a 95 % (`_meta_ci_assumed_95`, plus bas) est posee
// par ce calcul : effacee a l'entree comme le reste, une etude que ce run lit autrement ne la garde pas.
// P07, TOUR 2 (2026-10-20) : le plus haut palier admis sur ce poste, lu au relais au premier appel
// au modele (voir plus bas) ; `undefined` tant qu'il n'est pas lu, `null` si aucun palier n'est admis.
let PALIER_MAX;
const studies = [];
// ARRET_SORT_DE_LA_BOUCLE_v1 (2026-10-19, verification du lot « ecrans »). CE QUI ETAIT FAUX, rejoue
// par tests/test_arret_sort_de_la_boucle.py : cette boucle ne regardait pas la reponse d'arret du
// relais (`ultralab_cancelled`). Chaque article restant lisait son PDF (sans nommer son module, donc
// sans refus), recevait une reponse vide et sortait « no_data », « aucune donnee dans l'article », ce
// qui est faux. CE QUI CHANGE : la lecture du PDF nomme son module ; au premier refus (lecture ou
// appel au modele), la boucle cesse de travailler. L'article en cours et les suivants qui
// demandaient une lecture sortent « stopped » ; les rapports secondaires et les donnees deja
// extraites (aucun appel) sortent comme dans un run complet. Le calcul porte sur les etudes lues avant
// l'arret, et le rapport le dit. Une exception d'appel reste « no_data » : seul l'arret fait sortir.
const __metaMode = String((a0 && a0._module_mode) || 'meta-analysis');
let __metaArret = false;
for (let i=0;i<articles.length;i++){
  const art = articles[i];
  for (const __k of CALCULE_PAR_LE_RUN) delete art[__k];
  // STUDY_GROUPS_v1 (F3 v2) : companion papers - un seul rapport par ETUDE entre dans le pool
  // (unite d'analyse Cochrane = l'etude). Le regroupement est pose par /api/study-groups
  // (bouton Appliquer du chargeur de corpus) : les rapports non-primaires sont ecartes ici.
  if (art._study_group && art._study_group_primary === false){
    art._meta_status = 'companion_skipped';
    art._meta_included = false;
    art._meta_note = 'rapport secondaire du groupe ' + art._study_group + ' - seul le rapport principal est poole';
    continue;
  }
  // PONT : donnees deja extraites/verifiees -> on saute l'appel LLM (economie + tracabilite)
  const __reused = reuseExisting(art);
  if (__reused){ art._meta_data = __reused; art._meta_status='extracted'; art._meta_basis='reused'; studies.push(art); continue; }
  // Texte : PDF integral si dispo (les chiffres sont souvent dans les tableaux/resultats), sinon abstract
  // Apres l'arret, plus aucune lecture ni aucun appel (ARRET_SORT_DE_LA_BOUCLE_v1).
  if (__metaArret){ art._meta_status='stopped'; continue; }
  let basis='abstract', text='';
  const pdf = art.pdf_local || '';
  if (pdf){ try { const resp=await this.helpers.httpRequest({ method:'POST', url:PROXY+'/extract-pdf', body:JSON.stringify({ pdf_path:pdf, max_chars:24000, skip_biblio:true, _ultralab_module:__metaMode }), headers:{'Content-Type':'application/json'}, json:true, timeout:60000 }); if(resp&&resp.ultralab_cancelled===true){ __metaArret=true; } else if(resp&&resp.success&&resp.text){ text=resp.text.substring(0,22000); basis='fulltext'; } } catch(e){} }
  // Lecture du PDF refusee par l'arret : l'article n'est pas lu.
  if (__metaArret){ art._meta_status='stopped'; continue; }
  if (!text){ text=(art.abstract||'').toString(); basis='abstract'; }
  if (!text || text.length<40){ art._meta_status='no_text'; continue; }
  art._meta_basis=basis;
  // La provenance disait « plein texte » quand seuls 8 000 caracteres sur 22 000 etaient
  // partis. On enregistre desormais ce qui a REELLEMENT ete transmis.
  const __sel = choisirExtrait(text);
  art._meta_text_total = __sel.total;
  art._meta_text_sent = __sel.envoye;
  art._meta_text_selection = __sel.mode;
  const prompt = buildPrompt(art, __sel.texte);
  // P07 (2026-10-20) : LE PREMIER PALIER, BORNE, ET L'AVIS « RALENTI » LU. CE QUI ETAIT FAUX :
  // l'appel demandait num_ctx 32 768, exempte du num_ctx global (decision D12) sans aucun palier
  // materiel qui le borne, et la reponse n'etait lue que par `response` et `statut_garde` : un
  // modele deborde sur le processeur (avis « ralenti » du relais) n'etait dit nulle part. MESURE
  // (tests/test_meta_restes_lot0.py) : la plus longue invite de ce nœud (16 038 caracteres
  // d'article : tete, marque du saut et zone chiffree ; titre et critere coupes a 200 ; consigne)
  // fait 17 709 caracteres au plus, soit 6 563 jetons avec la reponse de 600 a l'estimateur du plan
